void push(int x) {
    h[++n] = x;                        // 맨 끝에 붙이고
    int i = n;
    while (i > 1 && h[i / 2] < h[i]) { // 부모보다 크면 올린다
        swap(h[i / 2], h[i]);
        i /= 2;
    }
}

// 카드 묶음을 둘씩 합치는 비용(두 묶음 크기의 합)의 총합을 최소로
priority_queue<long long, vector<long long>, greater<long long>> pq;  // 최소 힙
for (int i = 0; i < n; i++) pq.push(a[i]);
long long total = 0;
while (pq.size() > 1) {
    long long x = pq.top(); pq.pop();
    long long y = pq.top(); pq.pop();
    total += x + y;
    pq.push(x + y);
}

priority_queue<int> lo;                               // 작은 절반 (최대 힙)
priority_queue<int, vector<int>, greater<int>> hi;    // 큰 절반 (최소 힙)
void add(int x) {
    if (lo.empty() || x <= lo.top()) lo.push(x); else hi.push(x);
    if (lo.size() > hi.size() + 1) { hi.push(lo.top()); lo.pop(); }
    if (hi.size() > lo.size())     { lo.push(hi.top()); hi.pop(); }
}
int median() { return lo.top(); }   // 짝수 개이면 가운데 둘 중 작은 값
